 @Test void auditArbitraryJsonNullDecimalAndCycles(){var data=new LinkedHashMap<String,Object>();var nested=new ArrayList<>(Arrays.asList(null,new BigDecimal("99999999999999999999.123456"),false));data.put("values",nested);var a=audit();a.put("metadata",data);rows(List.of(a));var out=store.audit(request,1).getFirst();var metadata=(Map<?,?>)out.get("metadata");var values=(List<?>)metadata.get("values");assertNull(values.getFirst());assertEquals(nested.get(1),values.get(1));assertThrows(UnsupportedOperationException.class,values::clear);nested.clear();assertEquals(3,values.size());var cycle=new ArrayList<>();cycle.add(cycle);for(Object invalid:List.of(cycle,Double.NaN,Map.of(1,"bad"))){a=audit();a.put("metadata",invalid);rows(List.of(a));safe(()->store.audit(request,1));}a=audit();a.put("action","CLINICAL_READ");rows(List.of(a));safe(()->store.audit(request,1));}
 @Test void invalidRowsResultsetsTimestampsAndLimitsRollback(){var p=plan();p.put("createdAt","2026-11-04T00:00:00.123456789Z");rows(List.of(p));safe(()->store.plans(request));var u=user();u.put("active",1);rows(List.of(u));safe(()->store.users(request,1));rows(List.of(user(),user()));safe(()->store.users(request,1));results.add(new SqlServerExecutor.Result(List.of(),List.of()));safe(()->store.plans(request));results.add(new SqlServerExecutor.Result(List.of(List.of(),List.of()),List.of()));safe(()->store.plans(request));}
 @Test void directAuthorizationAndNoHttpAuthorityBeforeExecutor(){actor("SOP");assertEquals(403,assertThrows(ApiException.class,()->store.plans(request)).status);actor("SAD");request.setAttribute("health.tenant",new TenantRef(ID,"Synthetic","clinic","CLINIC","HUMAN","ACTIVE",List.of()));assertEquals(403,assertThrows(ApiException.class,()->store.plans(request)).status);request.setAttribute("health.tenant","bad");safe(()->store.plans(request));safe(()->store.plans(null));verifyNoInteractions(executor);}
 @Test void requiredJoinCommitAndVendorErrorsNoRetry(){rows(List.of(plan()));assertThrows(RuntimeException.class,()->manager.outer(()->{store.plans(request);assertEquals(List.of("begin:0"),manager.events);throw new RuntimeException("synthetic cancel");}));assertEquals("rollback",manager.events.getLast());rows(List.of(plan()));manager.failCommit=true;safe(()->store.plans(request));doThrow(new RuntimeException(new java.sql.SQLException("private driver",null,51001))).when(executor).execute(any(),any(),any(Object[].class));var error=assertThrows(ApiException.class,()->store.users(request,1));assertEquals(403,error.status);assertFalse(error.toString().contains("private"));verify(executor,times(3)).execute(any(),any(),any(Object[].class));}
 @Test void userSpecialtyAndAuditColumnsRequiredAndNullableTypesExact() throws Exception {for(String key:user().keySet()){var row=user();row.remove(key);rows(List.of(row));safe(()->store.users(request,1));}var specialty=realSpecialty();for(String key:specialty.keySet()){var row=new LinkedHashMap<>(specialty);row.remove(key);rows(List.of(row));safe(()->store.specialties(request,""));}for(String key:audit().keySet()){var row=audit();row.remove(key);rows(List.of(row));safe(()->store.audit(request,1));}var bad=user();bad.put("credential",1);rows(List.of(bad));safe(()->store.users(request,1));var badSpecialty=new LinkedHashMap<>(specialty);badSpecialty.put("profile","not object");rows(List.of(badSpecialty));safe(()->store.specialties(request,""));}
 @Test void auditScalarNullJsonAndSpecialtiesHaveNoInventedLimit() throws Exception {for(Object value:Arrays.asList(null,true,"text",new BigDecimal("123.456"),Arrays.asList(null,"item"))){var row=audit();row.put("metadata",value);rows(List.of(row));assertEquals(value,store.audit(request,1).getFirst().get("metadata"));}var specialty=realSpecialty();rows(Collections.nCopies(250,specialty));assertEquals(250,store.specialties(request,"%").size());rows(Collections.nCopies(201,user()));safe(()->store.users(request,200));rows(Collections.nCopies(201,audit()));safe(()->store.audit(request,200));}
 @Test void malformedActorUuidTokenAndMissingActorDoNotReachExecutor(){request.setAttribute("health.actor",new Actor("bad","Synthetic","qa@example.test",null,List.of("SAD"),"a".repeat(64)));safe(()->store.plans(request));request.setAttribute("health.actor",new Actor(ID,"Synthetic","qa@example.test",null,List.of("SAD"),"bad"));safe(()->store.plans(request));request.removeAttribute("health.actor");assertEquals(403,assertThrows(ApiException.class,()->store.plans(request)).status);verifyNoInteractions(executor);}


