 static com.mavric.health.saas.domain.Requests.Plan inputPlan(){return new com.mavric.health.saas.domain.Requests.Plan(" Synthetic \u4e2d\uD83E\uDDB7 ","", "PUBLISHED",1000000000000L,0L,0L,1,1,1,10000,100000,241,60,new LinkedHashSet<>(List.of("DOCTOR","CLINIC")),Set.of("HUMAN","ANIMAL"),Set.of("CORE","PORTAL"));}
 static com.mavric.health.saas.domain.Requests.Plan changePlan(String key,Object value){try{var p=inputPlan();var components=p.getClass().getRecordComponents();var types=new Class<?>[components.length];var args=new Object[components.length];for(int i=0;i<components.length;i++){types[i]=components[i].getType();args[i]=components[i].getName().equals(key)?value:components[i].getAccessor().invoke(p);}return (com.mavric.health.saas.domain.Requests.Plan)p.getClass().getDeclaredConstructor(types).newInstance(args);}catch(Exception e){throw new AssertionError(e);}}
 @Test void savePlanCreateUpdateUsesSingleSpBooleanAndExactWhitelist() throws Exception {var input=inputPlan();doAnswer(inv->{assertTrue(TransactionSynchronizationManager.isActualTransactionActive());assertEquals(SqlServerProcedure.SAAS_PLAN_SAVE,inv.getArgument(0));var c=inv.<SqlServerContext>getArgument(1);assertEquals(SqlServerContext.Scope.REQUEST,c.scope());Object[] a=(Object[])inv.getRawArguments()[2];String id=(String)a[0];assertEquals(UUID.fromString(id).toString(),id);var json=new tools.jackson.databind.ObjectMapper().readValue((String)a[1],Map.class);var expected=new tools.jackson.databind.ObjectMapper().readValue(new tools.jackson.databind.ObjectMapper().writeValueAsString(input),Map.class);assertEquals(expected,json);assertEquals(16,json.size());assertFalse(json.containsKey("id"));assertFalse(json.containsKey("actorId"));assertEquals(input.name(),json.get("name"));var r=plan();r.put("id",id);r.put("planId",id);r.put("version",9);r.put("currentVersion",9);r.put("passwordHash","private");calls.add(inv.getArgument(0));args.add(Arrays.asList(a.clone()));return new SqlServerExecutor.Result(List.of(List.of(r)),List.of());}).when(executor).execute(any(),any(),any(Object[].class));var created=store.savePlan(request,null,input);assertEquals(21,created.size());assertEquals(9,created.get("version"));assertEquals(true,args.getFirst().get(2));assertEquals(21,store.savePlan(request,ID,input).size());assertEquals(List.of(ID,args.getLast().get(1),false),args.getLast());assertEquals(2,calls.size());assertTrue(calls.stream().allMatch(v->v==SqlServerProcedure.SAAS_PLAN_SAVE));assertEquals(Set.of("DOCTOR","CLINIC"),input.kinds());assertThrows(UnsupportedOperationException.class,created::clear);}
 @Test void invalidPlanBoundsNullsEnumsSetsDoctorAndUtf16RejectBeforeSp(){var cases=new LinkedHashMap<String,List<Object>>();cases.put("name",Arrays.asList(null," ","x".repeat(101),"\uD83E\uDDB7".repeat(51)));cases.put("description",Arrays.asList(null,"x".repeat(501)));cases.put("status",Arrays.asList(null,"published","BAD"));for(String k:List.of("baseMinor","branchMinor","professionalMinor"))cases.put(k,List.of(-1L,1000000000001L));for(String k:List.of("includedBranches","includedProfessionals","includedSpecialties"))cases.put(k,List.of(0));cases.put("maxBranches",List.of(0,10001));cases.put("maxProfessionals",List.of(0,100001));cases.put("maxSpecialties",List.of(0,242));cases.put("annualDiscount",List.of(-1,61));cases.put("kinds",Arrays.asList(null,Set.of(),Set.of("bad"),new HashSet<>(Arrays.asList("CLINIC",null)),Set.of(1)));cases.put("domains",Arrays.asList(null,Set.of(),Set.of("bad")));cases.put("modules",Arrays.asList(null,Set.of(),Set.of("PORTAL"),Set.of("CORE","bad")));for(var entry:cases.entrySet())for(Object value:entry.getValue()){var p=changePlan(entry.getKey(),value);assertEquals(400,assertThrows(ApiException.class,()->store.savePlan(request,null,p)).status,entry.getKey());}assertEquals(400,assertThrows(ApiException.class,()->store.savePlan(request,null,null)).status);assertEquals(400,assertThrows(ApiException.class,()->store.savePlan(request,"bad",inputPlan())).status);assertEquals(400,assertThrows(ApiException.class,()->store.savePlan(request,ID,changePlan("includedProfessionals",4))).status);verifyNoInteractions(executor);}
