 void creationAnswer(java.util.function.Consumer<Map<String,Object>> corrupt){doAnswer(inv->{assertTrue(TransactionSynchronizationManager.isActualTransactionActive());var c=inv.<SqlServerContext>getArgument(1);assertEquals(SqlServerContext.Scope.REQUEST,c.scope());assertEquals(ID,c.actorId());assertNull(c.tenantId());var p=inv.<SqlServerProcedure>getArgument(0);Object[] a=(Object[])inv.getRawArguments()[2];calls.add(p);args.add(Arrays.asList(a.clone()));if(p!=SqlServerProcedure.SAAS_TENANT_CREATE)return results.removeFirst();var r=tenantRow();r.put("id",a[0]);r.put("ownerUserId",a[2]);r.put("status","TRIAL");corrupt.accept(r);return new SqlServerExecutor.Result(List.of(List.of(r)),List.of());}).when(executor).execute(any(),any(),any(Object[].class));}
